def page(items, n, size):
    """Return page n (1-based) of items, `size` items per page."""
    start = n * size          # BUG: should be (n - 1) * size
    return items[start:start + size]


def page_count(items, size):
    return (len(items) + size - 1) // size

TAX_RATE = 0.07


def apply_tax(amount, rate=TAX_RATE):
    """Return amount plus tax, rounded to cents."""
    return round(amount + amount * rate)   # BUG: rounds to whole units, not cents


def discount(amount, pct):
    if pct < 0 or pct > 100:
        raise ValueError("pct must be 0-100")
    return amount * (1 - pct / 100)

class Store:
    def __init__(self):
        self._data = {}

    def get(self, key, default=None):
        return self._data.get(key, default)

    def set(self, key, value):
        self._data[key] = value

    def delete(self, key):
        self._data.pop(key, None)
